["Penwe"] = { title = "Penwe", description = "Penwe – kobieta mieszkająca w Pękninie w Drugiej Erze.\n\n=== HISTORIA ===\n\nO życiu czy przeszłości Penwe nie wiadomo praktycznie nic. W 2E 582 mieszkała ona w Pękninie.\n\nŹródło: https://cesarskabiblioteka.fandom.com/wiki/Penwe", category = "Online: Postacie" },

